import{b as d,O as a,g as r,j as e}from"./chunks/framework.DcaUmd3X.js";const u=JSON.parse('{"title":"附录D · Oracle 版本差异速览","description":"","frontmatter":{},"headers":[],"relativePath":"database/oracle/appendix/version-diff/index.md","filePath":"数据库管理/Oracle从入门到精通/附录/D.版本差异速览.md","lastUpdated":1782140566000}'),o={name:"database/oracle/appendix/version-diff/index.md"};function c(l,t,h,i,n,b){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="附录d-·-oracle-版本差异速览" tabindex="-1">附录D · Oracle 版本差异速览 <a class="header-anchor" href="#附录d-·-oracle-版本差异速览" aria-label="Permalink to &quot;附录D · Oracle 版本差异速览&quot;">​</a></h1><h2 id="版本命名规则" tabindex="-1">版本命名规则 <a class="header-anchor" href="#版本命名规则" aria-label="Permalink to &quot;版本命名规则&quot;">​</a></h2><p>Oracle 的版本号遵循 <code>主版本.0.补丁版本</code> 格式，&quot;c&quot;、&quot;g&quot;、&quot;i&quot;、&quot;ai&quot; 是版本代号：</p><table tabindex="0"><thead><tr><th>代号</th><th>含义</th></tr></thead><tbody><tr><td>i</td><td>Internet（Oracle 8i/9i）</td></tr><tr><td>g</td><td>Grid（Oracle 10g/11g）</td></tr><tr><td>c</td><td>Cloud（Oracle 12c/18c/19c）</td></tr><tr><td>ai</td><td>AI（Oracle 23ai）</td></tr></tbody></table><h2 id="各版本关键特性" tabindex="-1">各版本关键特性 <a class="header-anchor" href="#各版本关键特性" aria-label="Permalink to &quot;各版本关键特性&quot;">​</a></h2><h3 id="oracle-11g-r2-2009" tabindex="-1">Oracle 11g R2（2009） <a class="header-anchor" href="#oracle-11g-r2-2009" aria-label="Permalink to &quot;Oracle 11g R2（2009）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>ASM 增强</td><td>自动存储管理更成熟</td></tr><tr><td>Data Guard 增强</td><td>活动 Data Guard（只读备库）</td></tr><tr><td>高级压缩</td><td>表空间级压缩选项</td></tr><tr><td>Deferred Segment Creation</td><td>延迟段创建，空表不占空间</td></tr><tr><td>版次（Edition-Based Redefinition）</td><td>在线升级应用</td></tr></tbody></table><h3 id="oracle-12c-r1-2013-r2-2017" tabindex="-1">Oracle 12c R1（2013）/ R2（2017） <a class="header-anchor" href="#oracle-12c-r1-2013-r2-2017" aria-label="Permalink to &quot;Oracle 12c R1（2013）/ R2（2017）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td><strong>CDB/PDB 多租户</strong></td><td>Container Database + Pluggable Database，一个实例管理多个数据库</td></tr><tr><td><strong>In-Memory 列存储</strong></td><td>内存中同时维护行列双格式</td></tr><tr><td>自适应执行计划</td><td>运行时自动调整连接方式和并行度</td></tr><tr><td>标识列（Identity Column）</td><td>类似 MySQL AUTO_INCREMENT</td></tr><tr><td>JSON 支持</td><td>原生 JSON 查询</td></tr><tr><td>在线迁移</td><td>在线移动数据文件、在线重建分区</td></tr></tbody></table><h3 id="oracle-18c-2018" tabindex="-1">Oracle 18c（2018） <a class="header-anchor" href="#oracle-18c-2018" aria-label="Permalink to &quot;Oracle 18c（2018）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>自治数据库（Autonomous Database）</td><td>自动调优、自动打补丁、自动备份（云版本）</td></tr><tr><td>Polymorphic Table Functions</td><td>多态表函数</td></tr><tr><td>私有临时表</td><td>基于内存的会话级临时表</td></tr></tbody></table><blockquote><p>18c 是 12c 系列的年度发布版，生命周期短，用户通常直接升级到 19c。</p></blockquote><h3 id="oracle-19c-2019-——-当前长期支持版" tabindex="-1">Oracle 19c（2019）—— 当前长期支持版 <a class="header-anchor" href="#oracle-19c-2019-——-当前长期支持版" aria-label="Permalink to &quot;Oracle 19c（2019）—— 当前长期支持版&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>自动索引</td><td>自动创建、监控、删除索引</td></tr><tr><td>实时统计信息</td><td>DML 操作时实时更新统计信息</td></tr><tr><td>SQL 隔离（SQL Quarantine）</td><td>自动隔离资源消耗过多的 SQL</td></tr><tr><td>混合分区表</td><td>支持内部分区和外部存储分区混合</td></tr><tr><td>Active Data Guard DML</td><td>备库允许 DML 操作</td></tr><tr><td>内存优化</td><td>自动内存管理增强</td></tr></tbody></table><blockquote><p>19c 是 12c 系列的<strong>长期支持版本（Long Term Release）</strong>，支持到 2027 年（ES 到 2030 年），是目前企业部署的主流版本。</p></blockquote><h3 id="oracle-21c-2021" tabindex="-1">Oracle 21c（2021） <a class="header-anchor" href="#oracle-21c-2021" aria-label="Permalink to &quot;Oracle 21c（2021）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>区块链表</td><td>防篡改的不可变表</td></tr><tr><td>原生 JSON 类型</td><td><code>JSON</code> 数据类型（不再用 VARCHAR2/CLOB 存 JSON）</td></tr><tr><td>JavaScript 存储过程</td><td>在数据库中运行 JavaScript（GraalVM）</td></tr><tr><td>SQL 宏</td><td>SQL 宏函数，编译期展开</td></tr><tr><td>AUTO 自动内存管理增强</td><td>自动根据负载调整 SGA/PGA</td></tr></tbody></table><blockquote><p>21c 是创新发布版（Innovation Release），生命周期较短，生产环境建议用 19c 或 23ai。</p></blockquote><h3 id="oracle-23ai-2023-——-最新长期支持版" tabindex="-1">Oracle 23ai（2023）—— 最新长期支持版 <a class="header-anchor" href="#oracle-23ai-2023-——-最新长期支持版" aria-label="Permalink to &quot;Oracle 23ai（2023）—— 最新长期支持版&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td><strong>AI 向量搜索</strong></td><td>内置向量存储和相似度搜索（Vector Search）</td></tr><tr><td><strong>JSON 关系二元性</strong></td><td>JSON 和关系型数据统一视图，一套数据两种用法</td></tr><tr><td><strong>True Cache</strong></td><td>内存缓存层，透明加速查询</td></tr><tr><td>无锁列</td><td>新值不阻塞旧值读取</td></tr><tr><td>直接布尔类型</td><td>原生 <code>BOOLEAN</code> 数据类型</td></tr><tr><td>SQL Firewall</td><td>防止 SQL 注入</td></tr><tr><td>可操作属性图</td><td>在关系数据上原生支持图查询（PGQL）</td></tr><tr><td>Schema 权限</td><td>细粒度权限控制到表级别</td></tr></tbody></table><blockquote><p>23ai 是最新的长期支持版本，名称中的 &quot;ai&quot; 代表了内置的 AI 向量处理能力。</p></blockquote><h2 id="版本选择建议" tabindex="-1">版本选择建议 <a class="header-anchor" href="#版本选择建议" aria-label="Permalink to &quot;版本选择建议&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐版本</th><th>原因</th></tr></thead><tbody><tr><td>学习入门</td><td>19c / 23ai Free</td><td>免费，功能完整</td></tr><tr><td>企业生产</td><td><strong>19c</strong></td><td>长期支持，最稳定，生态完善</td></tr><tr><td>新项目</td><td><strong>23ai</strong></td><td>最新 LTS，AI 能力，JSON 双模</td></tr><tr><td>云部署</td><td>Autonomous Database 19c/23ai</td><td>Oracle 云上自动管理</td></tr></tbody></table><h2 id="本教程适用的版本" tabindex="-1">本教程适用的版本 <a class="header-anchor" href="#本教程适用的版本" aria-label="Permalink to &quot;本教程适用的版本&quot;">​</a></h2><p>本教程以 <strong>Oracle 12c/19c</strong> 为基础编写，大部分内容也适用于 11g、18c、21c、23ai。</p><p>向后兼容性很好——12c 学到的内容在 23ai 中几乎全部有效。23ai 新增的特性（向量搜索、JSON 关系二元性等）属于增强功能，不影响基础使用。</p>',26)])])}const q=d(o,[["render",c]]);export{u as __pageData,q as default};
